# -*- coding: utf-8 -*-
"""Генератор страниц: франшиза/поставщики/помещения (обёртки над FritoLeadForm) и документы (доставка и оплата).
Оферту и политику генерирует tools/legal.py. После запуска обязательно: python3 tools/seo.py"""
import os
os.chdir(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))  # корень сайта
def head(title, preloads):
    pl='\n'.join(f'<link rel="preload" href="{p}.dc.html" as="fetch" crossorigin="anonymous">' for p in preloads)
    return f'''<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover, interactive-widget=resizes-content">
<title>{title} · Frito</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Montserrat:wght@600;800&display=swap" rel="stylesheet">
<!-- компоненты первого экрана: грузим параллельно, без цепочки -->
{pl}
<script src="./frito-i18n.js"></script>
<link rel="stylesheet" href="./frito.css">
<link rel="stylesheet" href="./info.css">
<script src="./frito.js"></script>
<script src="./support.js"></script>
</head>
<body>
<x-dc>
<helmet>
<style>
body{{margin:0;background:var(--surface-1)}}
a{{color:var(--primary);text-decoration:none}}a:hover{{color:var(--primary-dark)}}
*{{box-sizing:border-box}}
input::placeholder{{color:var(--ink-3)}}
input,select,button{{outline:none}}
</style>
</helmet>
<div class="f-page">
  <dc-import name="FritoHeader" back-label="В меню" hint-size="100%,72px"></dc-import>
'''
FOOT='''  <div class="f-footer-wrap"><dc-import name="FritoFooter" hint-size="100%,420px"></dc-import></div>
</div>
</x-dc>
<script type="text/x-dc" data-dc-script>
// контакты — из window.FritoContacts (frito.js): {{ c.phone }}, {{ c.waUrl }}, {{ c.email }}…
class Component extends DCLogic { renderVals() { return { c: window.FritoContacts || {} }; } }
</script>
</body>
</html>
'''
for fn,kind,title in [('franchise','franchise','Франшиза'),('suppliers','suppliers','Поставщикам'),('place','place','Предложить помещение')]:
    html=head(title,['FritoHeader','FritoLeadForm','FritoInput','FritoFooter'])+f'''  <main class="in-main">
    <dc-import name="FritoLeadForm" kind="{kind}" hint-size="100%,900px" style="width:100%;display:flex;justify-content:center"></dc-import>
  </main>
'''+FOOT
    open(fn+'.dc.html','w').write(html)

def doc(fn,title,eyebrow,lead,updated,sections):
    toc='\n'.join(f'        <a href="#{sid}">{h}</a>' for sid,h,_ in sections)
    body='\n'.join(f'      <section id="{sid}">\n        <h2>{h}</h2>\n{c}\n      </section>' for sid,h,c in sections)
    html=head(title,['FritoHeader','FritoFooter'])+f'''  <main class="in-main">
    <div class="in-doc">
      <div class="f-page-head in-doc__head">
        <span class="f-eyebrow">{eyebrow}</span>
        <h1 class="f-page-title">{title}</h1>
        <p class="f-page-lead">{lead}</p>
      </div>
      <div class="in-doc__grid">
      <nav class="in-toc" aria-label="Содержание">
        <span class="in-toc__title">СОДЕРЖАНИЕ</span>
{toc}
      </nav>
      <article class="in-body">
{body}
        <p class="in-muted">{updated}</p>
      </article>
      </div>
    </div>
  </main>
'''+FOOT
    open(fn+'.dc.html','w').write(html)

P=lambda *xs:'\n'.join(f'        <p>{x}</p>' for x in xs)
UL=lambda *xs:'        <ul>\n'+'\n'.join(f'          <li>{x}</li>' for x in xs)+'\n        </ul>'
OL=lambda *xs:'        <ol>\n'+'\n'.join(f'          <li>{x}</li>' for x in xs)+'\n        </ol>'
CARD=lambda ic,t,x:f'<div class="in-card"><span class="in-card__ic"'+(' style="background:var(--kaspi)"' if 'kaspi' in ic else '')+f'><img src="assets/{ic}" alt=""></span><span class="in-card__title">{t}</span><span class="in-card__text">{x}</span></div>'
ENTITY='[наименование юрлица], БИН [—]'

doc('delivery','Доставка и оплата','ПОКУПАТЕЛЯМ','Привозим горячим за 35–45 минут или готовим к самовывозу за 15 минут. Платите онлайн — Kaspi или картой.','Обновлено: октябрь 2026',[
 ('how','Как получить заказ','        <div class="in-cards">'+CARD('ic-delivery-p.svg','Доставка','Курьер привезёт заказ по адресу. Обычно 35–45 минут — точное время видно при выборе адреса.')+CARD('ic-pickup-p.svg','Самовывоз','Заберите заказ в ресторане. Готовим за 15 минут, без доплаты.')+'</div>'),
 ('zone','Где доставляем',P('Доставляем в Астане, Алматы, Шымкенте, Караганде и Актобе — в пределах зоны доставки вокруг наших ресторанов. Зону видно на карте при выборе адреса: если адрес вне её, сайт подскажет и предложит самовывоз.','Заказ везём из ближайшего к вам ресторана. Меню на сайте показывает то, что есть именно в нём.')),
 ('price','Стоимость доставки','        <table class="in-table"><thead><tr><th>Расстояние от ресторана</th><th>Стоимость</th></tr></thead><tbody><tr><td>до 2 км</td><td>600 ₸</td></tr><tr><td>2–4 км</td><td>900 ₸</td></tr><tr><td>4–7 км</td><td>1 200 ₸</td></tr><tr><td>больше 7 км</td><td>1 500 ₸</td></tr></tbody></table>\n        <div class="in-callout">При заказе от 8 000 ₸ доставка бесплатная.</div>'),
 ('time','Время работы',P('Рестораны работают ежедневно, большинство — с 11:30 до 02:00, в торговых центрах — по графику ТРЦ. Часы каждого ресторана указаны на карте при выборе самовывоза.','Можно оформить заказ «как можно скорее» или ко времени — выберите удобный слот при оформлении.')),
 ('pay','Способы оплаты','        <div class="in-cards">'+CARD('ic-kaspi-w.svg','Kaspi','Выставим счёт в приложение Kaspi на указанный номер — подтвердите оплату там.').replace('background:var(--primary-100)','')+CARD('ic-card-p.svg','Картой онлайн','Visa и Mastercard, оплата на защищённой странице банка.')+'</div>\n'+P('Мы начинаем готовить после оплаты. Если оплата не прошла, заказ сохраняется 15 минут — можно оплатить снова или выбрать другой способ.')),
 ('promo','Промокоды',P('Промокод вводится в корзине или при оформлении. Одновременно действует один промокод; скидка не распространяется на стоимость доставки, если в условиях акции не сказано иное.')),
 ('cancel','Отмена и возврат',P('Отменить заказ можно, пока ресторан не начал готовить, — на странице заказа. Деньги вернутся тем же способом, которым вы платили: обычно в течение 1–3 рабочих дней, срок зависит от банка.','Если что-то не так с заказом — не привезли позицию, остыло, перепутали — напишите нам в WhatsApp. Разберёмся и вернём деньги или привезём заново.')),
 ('contacts','Связаться с нами',P('WhatsApp: <a href="{{ c.waUrl }}" target="_blank" rel="noopener">{{ c.phone }}</a> · ежедневно {{ c.hours }}','Почта: <a href="{{ c.mailUrl }}">{{ c.email }}</a>')),
])

doc('offer','Публичная оферта','ДОКУМЕНТЫ','Договор на продажу блюд с доставкой и самовывозом через сайт и приложение Frito. Оформляя заказ, вы принимаете эти условия.','Редакция от [дата] · '+ENTITY,[
 ('terms','1. Термины',UL('<b>Продавец</b> — '+ENTITY+', адрес: [юридический адрес].','<b>Покупатель</b> — лицо, оформившее заказ на сайте frito.kz или в приложении Frito.','<b>Заказ</b> — выбранные Покупателем блюда и напитки с указанием способа получения, адреса или ресторана и способа оплаты.','<b>Сервис</b> — сайт frito.kz и мобильное приложение Frito.')),
 ('subject','2. Предмет договора',P('Продавец продаёт Покупателю блюда и напитки по ценам, указанным в Сервисе на момент оформления Заказа, а Покупатель принимает и оплачивает Заказ. По выбору Покупателя Продавец организует доставку Заказа или передаёт его в ресторане (самовывоз).')),
 ('accept','3. Акцепт оферты',P('Акцептом оферты считается оформление Заказа в Сервисе с подтверждением согласия с её условиями. С этого момента договор считается заключённым.')),
 ('order','4. Оформление заказа',OL('Покупатель выбирает блюда, способ получения и указывает адрес доставки или ресторан.','Покупатель указывает имя и номер телефона для связи.','Ассортимент зависит от выбранного ресторана: если блюда нет в наличии, Сервис сообщит об этом до оплаты.','Продавец подтверждает Заказ в Сервисе; статус Заказа отображается на странице заказа.')),
 ('price','5. Цена и оплата',P('Цены указаны в тенге и включают все налоги. Стоимость доставки рассчитывается по расстоянию от ресторана и показывается до оформления; при сумме Заказа от 8 000 ₸ доставка бесплатна. Оплата — через Kaspi, банковской картой онлайн или на кассе ресторана (только самовывоз). Подробнее — в разделе <a href="delivery.dc.html">«Доставка и оплата»</a>.')),
 ('delivery','6. Доставка и получение',P('Ориентировочное время доставки показывается при оформлении и может увеличиться из-за погоды, трафика или высокой загрузки — Покупатель видит актуальное время на странице заказа. Покупатель обеспечивает доступ курьера к адресу и находится на связи по указанному телефону. Заказ на самовывоз хранится в ресторане до конца рабочего дня.')),
 ('cancel','7. Отмена и возврат',P('Покупатель может отменить Заказ до начала приготовления. Если Заказ доставлен с недостатками (не та позиция, недовложение, нарушение качества), Покупатель сообщает об этом в день получения через WhatsApp; Продавец заменяет позицию или возвращает её стоимость. Возврат денежных средств производится тем же способом, которым была произведена оплата.')),
 ('resp','8. Ответственность',P('Продавец отвечает за качество блюд и соответствие Заказа. Продавец не отвечает за задержку, вызванную обстоятельствами непреодолимой силы или неверно указанными Покупателем данными. Информация о составе и аллергенах предоставляется по запросу.')),
 ('data','9. Персональные данные',P('Продавец обрабатывает персональные данные Покупателя в соответствии с <a href="privacy.dc.html">Политикой конфиденциальности</a> и законодательством Республики Казахстан.')),
 ('final','10. Прочие условия',P('Продавец вправе изменять оферту; новая редакция действует с момента публикации в Сервисе и не распространяется на уже оформленные Заказы. Споры решаются путём переговоров, а при недостижении согласия — в порядке, установленном законодательством Республики Казахстан.')),
 ('req','11. Реквизиты продавца',UL(ENTITY,'Юридический адрес: [—]','Почта: <a href="mailto:info@frito.kz">info@frito.kz</a> · WhatsApp: +7 700 938 00 00')),
])

doc('privacy','Политика конфиденциальности','ДОКУМЕНТЫ','Какие данные мы собираем, зачем и как их защищаем. Коротко: только то, что нужно для заказа, и никому не продаём.','Редакция от [дата] · '+ENTITY,[
 ('who','1. Кто обрабатывает данные',P('Оператор персональных данных — '+ENTITY+' (далее — Frito). Политика действует для сайта frito.kz и приложения Frito и составлена в соответствии с Законом Республики Казахстан «О персональных данных и их защите».')),
 ('what','2. Какие данные мы собираем',UL('Имя, номер телефона, электронная почта и дата рождения — если вы их указали;','адреса доставки и координаты точки на карте;','история заказов, оценки и отзывы;','технические данные: тип устройства, браузер, cookie и данные о посещениях сайта;','данные из заявок — анкеты кандидатов, заявки на франшизу, предложения поставщиков и помещений.')+'\n'+P('Данные банковских карт мы не получаем и не храним — оплату обрабатывают банк и Kaspi.')),
 ('why','3. Зачем',UL('Принять, приготовить и доставить заказ, сообщить его статус;','войти в личный кабинет по коду из WhatsApp, Telegram или SMS;','показать историю заказов и быстро повторить заказ;','отправлять акции и новости — только если вы на это согласились, отписаться можно в кабинете;','улучшать сервис и разбирать обращения;','рассматривать заявки кандидатов и партнёров.')),
 ('share','4. Кому передаём',P('Только тем, кто участвует в выполнении заказа: ресторану, курьеру (имя, телефон, адрес), платёжным сервисам и сервисам отправки сообщений. Также — государственным органам в случаях, предусмотренных законом. Мы не продаём персональные данные.')),
 ('keep','5. Сколько храним',P('Пока у вас есть аккаунт и ещё в течение срока, требуемого законодательством для бухгалтерского и налогового учёта. Данные из заявок — до окончания рассмотрения и не дольше одного года, если вы не стали нашим сотрудником или партнёром.')),
 ('rights','6. Ваши права',P('Вы можете узнать, какие данные мы храним, исправить их или попросить удалить, а также отозвать согласие на рассылки. Напишите на <a href="mailto:info@frito.kz">info@frito.kz</a> — ответим в течение 10 рабочих дней. Часть данных можно изменить самостоятельно в личном кабинете.')),
 ('cookies','7. Cookie',P('Сайт использует cookie и локальное хранилище браузера: чтобы помнить корзину, выбранный адрес, язык и вход в кабинет. Отключить cookie можно в настройках браузера — часть функций сайта при этом может работать некорректно.')),
 ('security','8. Защита данных',P('Передача данных шифруется, доступ к ним есть только у сотрудников, которым это нужно для работы. Мы регулярно проверяем меры защиты.')),
 ('changes','9. Изменения политики',P('Мы можем обновлять политику; новая редакция действует с момента публикации на этой странице. О существенных изменениях сообщим на сайте.')),
 ('contacts','10. Контакты',P('По вопросам персональных данных: <a href="mailto:info@frito.kz">info@frito.kz</a>.')),
])
print('ok')
